	SetMode(TestMode)
	r := New()
	r.GET("/", func(c *Context) { c.Status(http.StatusTeapot) })
	w := httptest.NewRecorder()
	req, _ := http.NewRequest(http.MethodGet, "/", nil)
	r.ServeHTTP(w, req)
	if w.Code != http.StatusTeapot {
		t.Fatalf("code = %d, want 418", w.Code)
	}
}
